#!/usr/bin/env python3
"""
Shared PreToolUse plumbing for the hooks in this directory.

Encodes the decision protocol once so each hook only has to express its policy:
https://code.claude.com/docs/en/hooks#pretooluse-decision-control

The one rule worth stating explicitly: a hook that has no opinion must emit `{}`
(defer), never `permissionDecision: "allow"`. "allow" approves the call without
prompting, so a hook that returns it for non-matching input silently
auto-approves every unrelated tool call and defeats the user's own permission
settings.
"""

from __future__ import annotations

import json
import os
import sys
from dataclasses import dataclass
from datetime import datetime, timezone

DEFAULT_LOG_DIR = os.path.join(os.path.expanduser("~"), ".claude", "hooks-logs")

# Tool inputs that can carry a path, across every tool these hooks match.
PATH_KEYS = ("file_path", "notebook_path", "path", "filePath", "file")

WRITE_TOOLS = frozenset({"Edit", "MultiEdit", "Write", "NotebookEdit"})
READ_TOOLS = frozenset({"Read", "Grep", "Glob"})

ACTION_VERBS = {
    "Read": "read",
    "Grep": "search",
    "Glob": "list",
    "Edit": "modify",
    "MultiEdit": "modify",
    "Write": "write",
    "NotebookEdit": "modify",
    "Bash": "run",
}


@dataclass(frozen=True)
class Decision:
    """A hook verdict. None from run() means defer."""

    decision: str
    reason: str
    system_message: str | None = None
    hook: str = ""


def env_flag(name: str) -> bool:
    """True for 1/true/yes/on, case-insensitive."""
    return os.environ.get(name, "").strip().lower() in ("1", "true", "yes", "on")


def read_input(hook: str) -> dict:
    """Parse the hook payload from stdin. Exits 1 (non-blocking) on bad JSON."""
    try:
        data = json.load(sys.stdin)
    except json.JSONDecodeError as error:
        print(f"{hook}: invalid JSON input: {error}", file=sys.stderr)
        sys.exit(1)
    return data if isinstance(data, dict) else {}


def tool_input(data: dict) -> dict:
    value = data.get("tool_input")
    return value if isinstance(value, dict) else {}


def paths_from(inputs: dict) -> list[str]:
    """Every path-like value in a tool input, deduplicated, in key order."""
    found: list[str] = []
    for key in PATH_KEYS:
        value = inputs.get(key)
        if isinstance(value, str) and value and value not in found:
            found.append(value)
    return found


def action_verb(tool_name: str) -> str:
    return ACTION_VERBS.get(tool_name, "use")


def defer() -> None:
    """Emit no decision: the normal permission flow applies."""
    sys.stdout.write("{}\n")


def decide(decision: str, reason: str, system_message: str | None = None) -> None:
    """Emit a permission decision ("deny" or "ask") for a PreToolUse call."""
    payload: dict = {
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": decision,
            "permissionDecisionReason": reason,
        }
    }
    if system_message:
        payload["systemMessage"] = system_message
    json.dump(payload, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")


# Permission modes in which nobody is there to answer an `ask`. Claude Code
# already denies an unanswered ask under dontAsk and in `-p` runs; under
# bypassPermissions the docs do not say, so the guards decide explicitly.
UNATTENDED_MODES = frozenset({"bypassPermissions", "dontAsk"})


def for_permission_mode(result: Decision | None, data: dict) -> Decision | None:
    """Turn a deterministic guard's `ask` into `deny` when no one can be asked.

    Only tightens: a deny stays a deny and a deferral stays a deferral. Set
    HOOK_UNATTENDED_KEEP_ASK=1 to leave asks unchanged.
    """
    if result is None or result.decision != "ask" or env_flag("HOOK_UNATTENDED_KEEP_ASK"):
        return result
    mode = data.get("permission_mode")
    if mode not in UNATTENDED_MODES:
        return result
    return Decision(
        "deny",
        f"{result.reason}\n\n[{result.hook or 'guard'}] Permission mode is {mode}, so no one can "
        "confirm this. It is denied instead; ask the user to run it or to switch modes.",
        result.system_message,
        result.hook,
    )


def emit(result: Decision | None) -> None:
    """Emit a hook result using the Claude Code decision protocol."""
    if result is None:
        defer()
        return
    decide(result.decision, result.reason, result.system_message)


def log_event(hook: str, payload: dict, log_dir_env: tuple[str, ...] = ()) -> None:
    """Append one JSONL record. Never raises — logging must not break a hook."""
    directory = next(
        (
            os.environ[name]
            for name in (*log_dir_env, "HOOKS_LOG_DIR")
            if os.environ.get(name)
        ),
        DEFAULT_LOG_DIR,
    )
    try:
        os.makedirs(directory, exist_ok=True)
        now = datetime.now(timezone.utc)
        record = {"ts": now.isoformat(), "hook": hook, **payload}
        with open(
            os.path.join(directory, f"{now:%Y-%m-%d}.jsonl"), "a", encoding="utf-8"
        ) as handle:
            handle.write(json.dumps(record, ensure_ascii=False) + "\n")
    except OSError:
        pass


def truncate(text: str, limit: int = 160) -> str:
    return text if len(text) <= limit else text[: limit - 3] + "..."

"""
The rule type shared by the dangerous_commands rule tables, plus argument helpers.

A rule matches one parsed command (shell_parse.SimpleCommand) instead of the
raw command text, so wrappers, nesting and quoting are already resolved when
it runs. `match` returns a short detail string naming what it saw, or None.
"""

from __future__ import annotations

import os
from collections.abc import Callable
from dataclasses import dataclass

from shell_parse import ParseResult, SimpleCommand
from shell_wrappers import CLI_OPTIONS_WITH_VALUE

CRITICAL = "critical"
HIGH = "high"
STRICT = "strict"
LEVEL_ORDER = {CRITICAL: 1, HIGH: 2, STRICT: 3}


@dataclass(frozen=True)
class RuleContext:
    parsed: ParseResult
    cwd: str


Matcher = Callable[[SimpleCommand, RuleContext], "str | None"]


@dataclass(frozen=True)
class DangerRule:
    rule_id: str
    level: str
    reason: str
    remediation: str
    match: Matcher
    # "deny", or "ask" for commands that are often legitimate but deserve a
    # human look. A deny can be softened to ask by configuration; an ask is
    # never softened further.
    decision: str = "deny"


# --------------------------------------------------------------------------- #
# Argument helpers
# --------------------------------------------------------------------------- #


def short_flag(args: tuple[str, ...] | list[str], letters: str, with_value: str = "") -> bool:
    """True if any of `letters` appears as a short option or in a cluster (`-fd`).

    Letters in `with_value` take a value, so the rest of the cluster is that
    value: in `git switch -cfeature`, `f` belongs to the branch name.
    """
    skip_next = False
    for arg in args:
        if skip_next:
            skip_next = False
            continue
        if arg == "--":
            return False
        if not (arg.startswith("-") and not arg.startswith("--") and len(arg) > 1):
            continue
        for position, letter in enumerate(arg[1:], start=1):
            if letter in letters:
                return True
            if letter in with_value:
                skip_next = position == len(arg) - 1
                break
    return False


def long_flag(args: tuple[str, ...] | list[str], *names: str, min_prefix: int = 5) -> bool:
    """True for `--name`, `--name=x`, or an unambiguous prefix such as `--forc`."""
    for arg in args:
        if arg == "--":
            return False
        if not arg.startswith("--"):
            continue
        key = arg.split("=", 1)[0]
        for name in names:
            if key == name or (len(key) >= min_prefix and name.startswith(key)):
                return True
    return False


def has(args: tuple[str, ...] | list[str], *tokens: str) -> bool:
    return any(arg in tokens for arg in args)


def operands(args: tuple[str, ...] | list[str], with_arg: frozenset[str] = frozenset()) -> list[str]:
    found: list[str] = []
    index, ended = 0, False
    while index < len(args):
        arg = args[index]
        if ended or not arg.startswith("-") or arg == "-":
            found.append(arg)
        elif arg == "--":
            ended = True
        elif arg in with_arg:
            index += 1
        index += 1
    return found


def expand(path: str, cwd: str) -> str:
    path = os.path.expanduser(path.replace("${HOME}", "~").replace("$HOME", "~"))
    return os.path.normpath(path if os.path.isabs(path) else os.path.join(cwd, path))


def is_inside(path: str, root: str) -> bool:
    return path == root or path.startswith(root.rstrip("/") + "/")


_BROAD_ROOTS = ("/", "/bin", "/boot", "/dev", "/etc", "/lib", "/opt", "/sbin", "/srv", "/usr",
                "/var", "/System", "/Library", "/Applications", "/Users", "/home", "/private")


def is_broad_target(path: str, cwd: str) -> bool:
    """Filesystem root, a system root, the home directory, or a strict ancestor of cwd."""
    resolved = expand(path, cwd)
    home = os.path.expanduser("~")
    strict_ancestor = resolved != cwd and is_inside(cwd, resolved)
    return resolved in _BROAD_ROOTS or resolved == home or strict_ancestor or os.path.dirname(resolved) == "/"


def positional_words(command: SimpleCommand) -> list[str]:
    """The command's positional words (subcommand first), skipping its options' values.

    `cargo +nightly publish` names a toolchain before the subcommand; it is skipped too.
    """
    words = operands(command.args, CLI_OPTIONS_WITH_VALUE.get(command.name, frozenset()))
    if command.name == "cargo":
        words = [word for word in words if not word.startswith("+")]
    return words

"""
System-level dangerous commands: disks, fetch-and-execute, permissions,
persistence, package publishing, bulk deletion, and switching off security
controls.

Sources: dcg system.disk / system.permissions / package_managers packs,
karanb192 block-dangerous-commands, sh-guard's download->execute taint rule,
cc-safety-net device/find rules, and the cancelli rubric axes for
persistence, weakened controls and fetch-and-execute.
"""

from __future__ import annotations

import os
import re

from danger_rule import (
    CRITICAL,
    HIGH,
    DangerRule,
    RuleContext,
    expand,
    has,
    is_broad_target,
    is_inside,
    long_flag,
    operands,
    positional_words,
    short_flag,
)
from shell_interpreters import interpreter_kind
from shell_parse import SimpleCommand, parse
from shell_wrappers import SHELLS, STDIN_PATHS, shell_invocation
from shell_writes import WRITE, written_paths

# --------------------------------------------------------------------------- #
# Disks and devices
# --------------------------------------------------------------------------- #

_HARMLESS_DEVICES = re.compile(r"^/dev/(?:null|zero|u?random|stdout|stderr|stdin|tty\w*|fd/\d+|pts/\d+)$")
_BLOCK_DEVICE = re.compile(r"^/dev/(?:sd|hd|vd|xvd|nvme|mmcblk|disk|rdisk|md|dm-|mapper/|loop)")


def _device_write(command: SimpleCommand, ctx: RuleContext) -> str | None:
    redirected = {r.target for r in command.redirects}
    for write in written_paths(command):
        if write.action != WRITE or write.dynamic:
            continue
        for target in _device_paths(write.path, command):
            # `dd of=` takes any device but the harmless ones; other writers
            # (`tee /dev/sda`, `cp image /dev/sda`, `> /dev/disk2`) a block device.
            raw_device = command.name == "dd" and not _HARMLESS_DEVICES.match(target)
            if _BLOCK_DEVICE.match(target) or (raw_device and write.path not in redirected):
                if write.path in redirected:
                    return f"redirect into {target}"
                return f"dd of={target}" if command.name == "dd" else f"{command.name} writes {target}"
    return None


def _device_paths(path: str, command: SimpleCommand) -> list[str]:
    """The /dev paths `path` may name: `cd /dev && dd of=sda` writes /dev/sda."""
    found: list[str] = []
    for directory in command.possible_cwds:
        if directory is None and not path.startswith(("/", "~")):
            continue
        target = os.path.normpath(os.path.join(directory or "/", os.path.expanduser(path)))
        if target.startswith("/dev/") and target not in found:
            found.append(target)
    return found


_FORMATTERS = re.compile(r"^(?:mkfs(?:\.\w+)?|mke2fs|mkswap|newfs(?:_\w+)?|wipefs|blkdiscard|sfdisk|cfdisk)$")
_DISKUTIL_DESTRUCTIVE = frozenset({"eraseDisk", "eraseVolume", "partitionDisk", "zeroDisk",
                                   "randomDisk", "secureErase", "reformat", "deleteVolume",
                                   "apfs"})


def _names_device(command: SimpleCommand) -> bool:
    """A /dev path, from any directory the command may run in (`cd /dev && mkfs
    sdb1`), or a computed one; formatting an image file is harmless."""
    return any(a.startswith("/dev/") or "$" in a or "`" in a or _device_paths(a, command)
               for a in operands(command.args))


# parted commands that only report; any other command (or none: interactive) may write.
_PARTED_READ_ONLY = frozenset({"print", "p", "help", "h", "version", "v", "unit", "align-check", "quit", "q"})
_PARTED_UNITS = frozenset({"s", "B", "kB", "MB", "MiB", "GB", "GiB", "TB", "TiB", "%", "cyl", "chs", "compact"})


def _parted(command: SimpleCommand) -> str | None:
    """`parted -l` and `parted DEV print` only read; `parted DEV mklabel gpt print`
    writes a new label before printing it, and bare `parted DEV` is interactive."""
    if short_flag(command.args, "l") or long_flag(command.args, "--list"):
        return None
    words = operands(command.args, frozenset({"-a", "--align"}))[1:]  # after the device
    commands = [w for w in words if not w.isdigit() and w not in _PARTED_UNITS and w not in ("minimal", "optimal")]
    if commands and all(w in _PARTED_READ_ONLY for w in commands):
        return None
    return "parted"


def _disk_format(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if _FORMATTERS.match(command.name) and _names_device(command):
        return command.name
    if command.name == "parted":
        return _parted(command)
    if command.name in ("fdisk", "gdisk", "sgdisk") and not short_flag(command.args, "l"):
        return command.name
    if command.name == "diskutil" and command.args and command.args[0] in _DISKUTIL_DESTRUCTIVE:
        # `diskutil apfs list` is harmless; `diskutil apfs deleteContainer` is not.
        apfs_destructive = command.args[1:2] and command.args[1].startswith(("delete", "erase"))
        if command.args[0] != "apfs" or apfs_destructive:
            return f"diskutil {command.args[0]}"
    return None


# --------------------------------------------------------------------------- #
# Fetch-and-execute and decode-and-execute
# --------------------------------------------------------------------------- #

_FETCHERS = frozenset({"curl", "wget", "fetch", "aria2c", "http", "https", "xh", "xhs", "httpie",
                       "nc", "ncat", "netcat", "socat", "lwp-request", "GET"})
_DECODERS = frozenset({"base64", "base32", "xxd", "openssl", "uudecode", "gunzip", "zcat", "rev"})
_FETCH_IN_ARG = re.compile(r"(?:\$\(|<\(|`)\s*(?:\S*/)?(?:curl|wget|fetch|aria2c|http|https|xh)\b")


def _executes_stdin(command: SimpleCommand) -> bool:
    """A shell or interpreter that will run whatever arrives on stdin."""
    name, args = command.name, command.args
    if name in SHELLS:
        shell = shell_invocation(name, args)
        return shell.reads_stdin and not shell.syntax_only
    if interpreter_kind(name):
        script_args = operands(args, frozenset({"-W", "-X", "-m", "-r", "-I", "-M"}))
        return not script_args or script_args[0] in STDIN_PATHS
    return name in ("eval", "source", ".")


def _pipeline_sources(command: SimpleCommand, ctx: RuleContext) -> list[SimpleCommand]:
    found: list[SimpleCommand] = []
    current = ctx.parsed.previous_stage(command)
    while current is not None:
        found.append(current)
        current = ctx.parsed.previous_stage(current)
    return found


def _fetch_and_execute(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if _executes_stdin(command):
        for source in _pipeline_sources(command, ctx):
            if source.name in _FETCHERS:
                return f"{source.name} ... | {command.name}"
    if command.name in SHELLS or command.name in ("eval", "source", ".") or interpreter_kind(command.name):
        for arg in command.args:
            if _FETCH_IN_ARG.search(arg):
                return f"{command.name} runs downloaded code: {arg[:60]}"
        # `bash < <(curl -fsSL URL)`: the download arrives as stdin.
        if _executes_stdin(command):
            for redirect in command.redirects:
                if redirect.op == "<" and _FETCH_IN_ARG.search(redirect.target):
                    return f"{command.name} < downloaded code: {redirect.target[:60]}"
    return None


def _executed_files(command: SimpleCommand, ctx: RuleContext) -> list[str]:
    """Files `command` runs as a program: a script argument, `./tool`, `source f`,
    or a file a shell or interpreter reads on stdin (`< f`, `cat f | bash`)."""
    files: list[str] = []
    if command.name in SHELLS:
        shell = shell_invocation(command.name, command.args)
        if shell.script and not shell.syntax_only:
            files.append(shell.script)
    elif interpreter_kind(command.name):
        script = operands(command.args, frozenset({"-W", "-X", "-m", "-r", "-I", "-M", "-c", "-e"}))[:1]
        files += [s for s in script if s not in STDIN_PATHS]
    elif command.name in ("source", ".") and command.args:
        files.append(command.args[0])
    elif "/" in (command.argv[0] if command.argv else "") and not command.dynamic_head:
        files.append(command.argv[0])
    if _executes_stdin(command):
        files += [r.target for r in command.redirects if r.op == "<" and not r.dynamic]
        for source in _pipeline_sources(command, ctx):
            if source.name == "cat" and not source.dynamic_head:
                files += [f for f in operands(source.args, frozenset()) if f not in STDIN_PATHS]
    return files


def _absolute(path: str, directory: str | None) -> str | None:
    expanded = os.path.expanduser(path)
    if os.path.isabs(expanded):
        return os.path.normpath(expanded)
    return None if directory is None else os.path.normpath(os.path.join(directory, expanded))


def _run_downloaded(command: SimpleCommand, ctx: RuleContext) -> str | None:
    """`curl -o x.sh URL && bash x.sh`: running a file this same line downloaded."""
    executed = {a for f in _executed_files(command, ctx) for d in command.possible_cwds
                if (a := _absolute(f, d))}
    if not executed:
        return None
    for earlier in ctx.parsed.commands:
        if earlier is command:
            break
        if earlier.name not in _FETCHERS:
            continue
        for write in written_paths(earlier):
            for directory in earlier.possible_cwds:
                if _absolute(write.path, directory) in executed:
                    return f"{earlier.name} downloads {write.path}, then {command.name} runs it"
    return None


def _uninspected_program(command: SimpleCommand, ctx: RuleContext) -> str | None:
    """A script, Makefile or recipe set this command runs that could not be read
    (too large, binary, or past a resolver limit)."""
    for skipped, label in ctx.parsed.skipped_sources:
        if skipped is command:
            return f"{command.name} runs {label} (could not be inspected)"
    return None


def _incomplete_analysis(command: SimpleCommand, ctx: RuleContext) -> str | None:
    """The parser stopped early (nesting depth, wrapper chain, expansion limits):
    what it did not see may be anything. Reported once, on the first command."""
    if ctx.parsed.truncated and ctx.parsed.commands and command is ctx.parsed.commands[0]:
        return "the command is nested or expanded beyond what the guards analyse"
    return None


def _decode_and_execute(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.dynamic_head and command.argv:
        # `$(base64 -d <<< cm0=) -rf x`: the program to run is decoded text.
        body = re.fullmatch(r"\$\((.*)\)|`(.*)`", command.argv[0], re.DOTALL)
        if body:
            for source in parse(next(g for g in body.groups() if g is not None), "/").commands:
                if _decodes(source):
                    return f"$({source.name} (decode) ...) as the command"
    if not _executes_stdin(command):
        return None
    for source in _pipeline_sources(command, ctx):
        if _decodes(source):
            return f"{source.name} (decode) ... | {command.name}"
    return None


def _decodes(source: SimpleCommand) -> bool:
    return source.name in _DECODERS and (
        short_flag(source.args, "dDr") or long_flag(source.args, "--decode") or
        source.name in ("uudecode", "gunzip", "zcat", "rev"))


# --------------------------------------------------------------------------- #
# Permissions
# --------------------------------------------------------------------------- #

_WORLD_WRITABLE = re.compile(r"^(?:[0-7]?[0-7][0-7][2367]|(?:[ugoa]*[ao][ugoa]*|)\+[rwxXst]*w)")
_SETUID = re.compile(r"^(?:[4267][0-7]{3}|[ugoa]*\+[rwxX]*s)")


def _chmod_dangerous(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name != "chmod":
        return None
    words = operands(command.args, frozenset({"--reference"}))
    if any(a == "--reference" or a.startswith("--reference=") for a in command.args):
        # `chmod --reference=RFILE FILE...`: the mode comes from RFILE; every operand is a target.
        mode, targets = "", words
    elif len(words) < 2:
        return None
    else:
        mode, targets = words[0], words[1:]
    if not targets:
        return None
    recursive = short_flag(command.args, "R") or long_flag(command.args, "--recursive")
    if mode and _SETUID.match(mode):
        return f"chmod {mode} (setuid/setgid)"
    if mode and _WORLD_WRITABLE.match(mode) and (recursive or any(is_broad_target(t, ctx.cwd) for t in targets)):
        return f"chmod {'-R ' if recursive else ''}{mode}"
    if recursive and any(is_broad_target(t, ctx.cwd) for t in targets):
        return f"chmod -R on {targets[0]}"
    return None


def _chmod_world_single(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name != "chmod":
        return None
    words = operands(command.args)
    return f"chmod {words[0]}" if len(words) >= 2 and _WORLD_WRITABLE.match(words[0]) else None


def _chown_broad(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name not in ("chown", "chgrp"):
        return None
    recursive = short_flag(command.args, "R") or long_flag(command.args, "--recursive")
    words = operands(command.args, frozenset({"--reference", "--from"}))
    # `chown --reference=RFILE FILE...`: no owner operand, every operand is a target.
    by_reference = any(a == "--reference" or a.startswith("--reference=") for a in command.args)
    targets = words if by_reference else words[1:]
    if recursive and any(is_broad_target(t, ctx.cwd) for t in targets):
        return f"{command.name} -R {targets[0]}"
    return None


# --------------------------------------------------------------------------- #
# Persistence: scheduled jobs and services
# --------------------------------------------------------------------------- #


def _crontab_remove(command: SimpleCommand, ctx: RuleContext) -> str | None:
    return "crontab -r" if command.name == "crontab" and short_flag(command.args, "r") else None


def _crontab_install(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name != "crontab" or short_flag(command.args, "lr"):
        return None
    return "crontab (install a new table)"


def _schedule(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name in ("at", "batch") and not short_flag(command.args, "lrdc"):
        return command.name
    if command.name == "launchctl" and command.args and command.args[0] in (
            "load", "bootstrap", "enable", "submit", "kickstart"):
        return f"launchctl {command.args[0]}"
    if command.name == "systemctl" and positional_words(command)[:1] in (
            ["enable"], ["link"], ["preset"], ["edit"], ["set-property"]):
        return f"systemctl {positional_words(command)[0]}"
    return None


# --------------------------------------------------------------------------- #
# Publishing packages and artifacts
# --------------------------------------------------------------------------- #

_PUBLISH = {
    "npm": ("publish", "unpublish", "deprecate", "dist-tag"),
    "pnpm": ("publish",),
    "yarn": ("publish", "npm"),
    "bun": ("publish",),
    "cargo": ("publish", "yank", "owner"),
    "gem": ("push", "yank", "owner"),
    "twine": ("upload",),
    "uv": ("publish",),
    "poetry": ("publish",),
    "flit": ("publish",),
    "hatch": ("publish",),
    "pdm": ("publish",),
    "vsce": ("publish", "unpublish"),
    "ovsx": ("publish",),
    "pod": ("trunk",),
    "dotnet": ("nuget",),
    "mvn": ("deploy",),
    "gradle": ("publish",),
    "goreleaser": ("release",),
}


def _publish(command: SimpleCommand, ctx: RuleContext) -> str | None:
    verbs = _PUBLISH.get(command.name)
    if not verbs:
        return None
    words = positional_words(command)
    if not words or words[0] not in verbs:
        return None
    if command.name == "yarn" and words[0] == "npm" and (len(words) < 2 or words[1] != "publish"):
        return None
    if has(command.args, "--dry-run", "-n") or long_flag(command.args, "--dry-run"):
        return None
    return f"{command.name} {words[0]}"


def _push_artifact(command: SimpleCommand, ctx: RuleContext) -> str | None:
    words = positional_words(command)
    if command.name in ("docker", "podman", "buildah") and words[:1] == ["push"]:
        return f"{command.name} push"
    if command.name == "gh" and words[:2] in (["release", "create"], ["release", "delete"], ["repo", "delete"]):
        return "gh " + " ".join(words[:2])
    return None


# --------------------------------------------------------------------------- #
# Bulk deletion that is not `rm -rf`
# --------------------------------------------------------------------------- #


# find primaries that consume the next word (so `-name -delete` is a pattern).
_FIND_ARITY_ONE = frozenset({
    "-amin", "-anewer", "-atime", "-Bmin", "-Bnewer", "-Btime", "-cmin", "-cnewer", "-context",
    "-ctime", "-flags", "-fls", "-fprint", "-fprint0", "-fstype", "-gid", "-group", "-ilname",
    "-iname", "-inum", "-ipath", "-iregex", "-iwholename", "-links", "-lname", "-maxdepth",
    "-mindepth", "-mmin", "-mnewer", "-mtime", "-name", "-newer", "-path", "-perm", "-printf",
    "-regex", "-regextype", "-samefile", "-size", "-type", "-uid", "-used", "-user", "-wholename",
    "-xattrname", "-xtype", "-files0-from",
})
_FIND_EXEC = frozenset({"-exec", "-execdir", "-ok", "-okdir"})
_TEMP_ROOTS = ("/tmp", "/var/tmp", "/private/tmp", "/private/var/tmp", "/var/folders")


def _find_deletes(args: tuple[str, ...]) -> bool:
    """True when `-delete` is a find action, not an argument of another primary."""
    index = 0
    while index < len(args):
        arg = args[index]
        if arg in _FIND_EXEC:
            while index < len(args) and args[index] not in (";", "+"):
                index += 1
        elif arg == "-fprintf":
            index += 2
        elif arg in _FIND_ARITY_ONE or arg.startswith("-newer"):
            index += 1
        elif arg == "-delete":
            return True
        index += 1
    return False


def _is_temp(path: str, cwd: str) -> bool:
    if path.startswith(("$TMPDIR", "${TMPDIR}")):
        return True
    resolved = os.path.realpath(expand(path, cwd))
    return any(is_inside(resolved, os.path.realpath(root)) and resolved != os.path.realpath(root)
               for root in _TEMP_ROOTS)


def _find_starting_points(args: tuple[str, ...]) -> list[str]:
    points = []
    for arg in args:
        if arg.startswith(("-", "(", "!", ")")):
            break
        points.append(arg)
    return points or ["."]


def _find_delete(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name not in ("find", "gfind") or not _find_deletes(command.args):
        return None
    points = _find_starting_points(command.args)
    follows = any(a in ("-L", "-follow", "-H") for a in command.args)
    outside = [p for p in points
               if is_broad_target(p, ctx.cwd)
               or not (is_inside(expand(p, ctx.cwd), ctx.cwd) or _is_temp(p, ctx.cwd))]
    if outside or follows:
        return f"find {' '.join(points)} -delete (outside the working directory)"
    return None


def _find_delete_local(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name in ("find", "gfind") and _find_deletes(command.args):
        return f"find {' '.join(_find_starting_points(command.args))} -delete"
    return None


def _shred(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name in ("shred", "srm") and operands(command.args):
        return command.name
    if command.name == "mv" and operands(command.args)[-1:] == ["/dev/null"]:
        return "mv ... /dev/null"
    return None


# --------------------------------------------------------------------------- #
# System state and security controls
# --------------------------------------------------------------------------- #


def _power(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name in ("shutdown", "reboot", "halt", "poweroff"):
        return command.name
    if command.name in ("init", "telinit") and operands(command.args)[:1] in (["0"], ["6"]):
        return f"{command.name} {command.args[0]}"
    if command.name == "systemctl" and any(a in ("poweroff", "reboot", "halt", "kexec") for a in command.args):
        return "systemctl poweroff/reboot"
    return None


def _kill_targets(args: tuple[str, ...]) -> list[str]:
    """PIDs passed to kill. `kill [-s SIG | -n NUM | -SIG] pid...`: only the first
    dash word is a signal, so in `kill -9 -1` the `-1` is the PID for everything."""
    index = 0
    if args[:1] and args[0] in ("-l", "-L", "--list"):
        return []
    if args[:1] and args[0] in ("-s", "-n", "--signal"):
        index = 2
    elif args[:1] and args[0].startswith("-") and args[0] != "--":
        index = 1
    if index < len(args) and args[index] == "--":
        index += 1
    return list(args[index:])


def _kill_everything(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name == "kill" and any(pid in ("-1", "1") for pid in _kill_targets(command.args)):
        return "kill -1 / kill 1 (every process / init)"
    if command.name in ("killall5",):
        return command.name
    return None


_SECURITY_OFF = (
    ("csrutil", ("disable",)),
    ("spctl", ("--master-disable", "--global-disable", "--disable")),
    ("setenforce", ("0", "Permissive", "permissive")),
    ("ufw", ("disable",)),
    ("pfctl", ("-d",)),
)
_SECURITY_SERVICES = re.compile(r"^(?:firewalld|ufw|apparmor|auditd|selinux|fail2ban|clamav\S*|"
                                r"com\.apple\.(?:alf|security)\S*)$")


def _weaken_security(command: SimpleCommand, ctx: RuleContext) -> str | None:
    for name, args in _SECURITY_OFF:
        if command.name == name and any(a in args for a in command.args):
            return f"{name} {' '.join(a for a in command.args if a in args)}"
    if command.name in ("iptables", "ip6tables") and (short_flag(command.args, "F") or long_flag(command.args, "--flush")
                                                      or (has(command.args, "-P", "--policy") and "ACCEPT" in command.args)):
        return f"{command.name} flush/accept-all"
    if command.name == "nft" and has(command.args, "flush") and has(command.args, "ruleset"):
        return "nft flush ruleset"
    verb = positional_words(command)[:1]
    stops = verb and verb[0] in ("stop", "disable", "mask", "unload", "bootout")
    if command.name in ("systemctl", "launchctl") and stops and any(
        _SECURITY_SERVICES.match(os.path.basename(a).removesuffix(".service").removesuffix(".plist"))
        for a in command.args[1:]
    ):
        return f"{command.name} {verb[0]} (security service)"
    if command.name == "defaults" and "LSQuarantine" in command.args:
        return "defaults write LSQuarantine"
    if command.name in ("npm", "pnpm", "yarn") and has(command.args, "strict-ssl") and has(command.args, "false"):
        return f"{command.name} config strict-ssl false"
    if command.name in ("pip", "pip3") and any("trusted-host" in a for a in command.args) and has(command.args, "config"):
        return "pip config trusted-host"
    return None


def _clear_history(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if command.name == "history" and short_flag(command.args, "cw"):
        return "history -c"
    if command.name == "unset" and has(command.args, "HISTFILE"):
        return "unset HISTFILE"
    if command.name in ("rm", "shred", "truncate") and any(
            os.path.basename(a) in (".bash_history", ".zsh_history", ".zhistory", ".python_history")
            for a in command.args):
        return f"{command.name} shell history"
    return None


_FORK_BOMB = re.compile(r":\s*\(\s*\)\s*\{\s*:\s*\|\s*:\s*&\s*\}")


def _fork_bomb(command: SimpleCommand, ctx: RuleContext) -> str | None:
    # A fork bomb is a function definition; look at the source text it came from.
    if command.name == ":" and command.stage == 1:
        source = ctx.parsed.previous_stage(command)
        if source is not None and source.name == ":":
            return "fork bomb"
    return None


_DISK_HINT = "This can destroy a whole disk or filesystem. Never run it from an agent; describe it to the user."
_FETCH_HINT = (
    "Do not pipe downloaded code into a shell or interpreter. Download to a file, show the user "
    "what it does (or its checksum and source), and let them run it."
)
_PERSIST_HINT = "This makes code run later or on a schedule. Describe the change and let the user make it."
_PUBLISH_HINT = "Publishing is public and often irreversible. Run with --dry-run and let the user publish."

SYSTEM_RULES: tuple[DangerRule, ...] = (
    DangerRule("device-write", CRITICAL, "writes directly to a block device", _DISK_HINT, _device_write),
    DangerRule("disk-format", CRITICAL, "formats, partitions or wipes a disk", _DISK_HINT, _disk_format),
    DangerRule("fetch-and-execute", CRITICAL, "runs code downloaded from the network", _FETCH_HINT,
               _fetch_and_execute),
    DangerRule("run-downloaded", CRITICAL, "runs a file downloaded earlier in the same command", _FETCH_HINT,
               _run_downloaded),
    DangerRule("uninspected-program", HIGH, "runs program text the guards could not read",
               "Confirm with the user, or run the steps it needs directly so they can be checked.",
               _uninspected_program, decision="ask"),
    DangerRule("incomplete-analysis", HIGH, "could not be analysed completely",
               "Simplify the command (fewer nested shells, wrappers or expansions) so it can be checked, "
               "or confirm with the user.", _incomplete_analysis, decision="ask"),
    DangerRule("decode-and-execute", CRITICAL, "decodes and runs hidden code", _FETCH_HINT,
               _decode_and_execute),
    DangerRule("fork-bomb", CRITICAL, "exhausts process limits", _DISK_HINT, _fork_bomb),
    DangerRule("chmod-dangerous", HIGH, "makes files world-writable, setuid, or re-permissions a broad tree",
               "Grant the narrowest permission that works (e.g. `chmod u+x script.sh`).", _chmod_dangerous),
    DangerRule("chown-broad", HIGH, "changes ownership of a system or home tree",
               "Change ownership of the specific files that need it.", _chown_broad),
    DangerRule("crontab-remove", HIGH, "crontab -r deletes every scheduled job without confirmation",
               "Use `crontab -l` to show the table and let the user edit it.", _crontab_remove, decision="ask"),
    DangerRule("crontab-install", HIGH, "installing a crontab schedules code to run later", _PERSIST_HINT,
               _crontab_install),
    DangerRule("publish-package", HIGH, "publishes or unpublishes a package", _PUBLISH_HINT, _publish),
    DangerRule("find-delete-outside", HIGH, "find -delete outside the working directory or following symlinks",
               "Run with -print first and let the user delete.", _find_delete, decision="ask"),
    DangerRule("shred", HIGH, "irrecoverably destroys file contents",
               "Use plain `rm` for files the task owns; let the user shred anything else.", _shred, decision="ask"),
    DangerRule("power-state", HIGH, "shuts down or reboots the machine",
               "Ask the user to do this.", _power),
    DangerRule("kill-everything", HIGH, "signals every process or init", "Kill specific PIDs.", _kill_everything),
    DangerRule("weaken-security", HIGH, "disables a security control (SIP, Gatekeeper, SELinux, firewall, TLS checks)",
               "Do not switch off security controls; fix the underlying problem or ask the user.",
               _weaken_security),
    # Common and often legitimate: confirm rather than block.
    DangerRule("chmod-world-writable", HIGH, "makes a file world-writable",
               "Prefer `chmod u+w` or `chmod g+w`.", _chmod_world_single, decision="ask"),
    DangerRule("schedule-job", HIGH, "schedules or enables something that runs later", _PERSIST_HINT,
               _schedule, decision="ask"),
    DangerRule("push-artifact", HIGH, "pushes an image or release, or deletes a repository", _PUBLISH_HINT,
               _push_artifact, decision="ask"),
    DangerRule("find-delete", HIGH, "find -delete removes every match with no undo",
               "Run the same find with -print first and show the user.", _find_delete_local, decision="ask"),
    DangerRule("clear-history", HIGH, "erases shell history (covers tracks)",
               "Leave shell history alone.", _clear_history, decision="ask"),
)

"""
Git commands that destroy work, rewrite shared history, or weaken git's safety.

Rule set follows cc-safety-net's git rules (MIT, kenryu42/cc-safety-net,
src/gate/analyzer/git/rules.ts) and dcg's core.git pack: discarding
uncommitted changes, force pushes and remote deletes, force branch deletes,
dropping stashes, rewriting history, plus config that hides commands (`!`
aliases) or moves hooks (`core.hooksPath`).

The safe spellings stay allowed: `push --force-with-lease`, `branch -d`,
`clean -n`, `restore --staged`, `checkout -b`, `stash pop`, `rm --cached`.
"""

from __future__ import annotations

import os
import re
from dataclasses import dataclass

from danger_rule import (
    HIGH,
    STRICT,
    DangerRule,
    RuleContext,
    has,
    long_flag,
    operands,
    short_flag,
)
from shell_parse import SimpleCommand

# Global options that take a value (`git -C dir`, `git -c k=v`).
_GLOBAL_WITH_VALUE = frozenset({"-c", "-C", "--git-dir", "--work-tree", "--namespace",
                                "--super-prefix", "--config-env", "--exec-path", "--list-cmds"})


@dataclass(frozen=True)
class Git:
    subcommand: str
    args: tuple[str, ...]
    config: tuple[str, ...]  # `key=value` from -c / --config-env, lower-cased keys
    # --config-env keys whose environment variable has no value we can see.
    unresolved: tuple[str, ...] = ()
    # Where git works: the command's possible directories, then each `-C DIR`
    # in turn. Empty when no directory is known.
    directories: tuple[str, ...] = ()


def git_invocation(command: SimpleCommand) -> Git | None:
    if command.name != "git" or command.dynamic_head:
        return None
    args, config, from_env = list(command.args), [], []
    directories = [d for d in command.possible_cwds if d is not None]
    index = 0
    while index < len(args):
        arg = args[index]
        if arg in _GLOBAL_WITH_VALUE:
            if arg == "-C" and index + 1 < len(args):
                # `git -C a -C b`: b is relative to a.
                target = os.path.expanduser(args[index + 1])
                directories = ([target] if os.path.isabs(target)
                               else [os.path.join(d, target) for d in directories])
            if arg == "-c" and index + 1 < len(args):
                config.append(args[index + 1])
            elif arg == "--config-env" and index + 1 < len(args):
                from_env.append(args[index + 1])
            index += 2
            continue
        if arg.startswith("-c") and len(arg) > 2:
            config.append(arg[2:])
        elif arg.startswith("--config-env="):
            from_env.append(arg.split("=", 1)[1])
        if arg.startswith("-"):
            index += 1
            continue
        break
    else:
        arg = ""
    unresolved: list[str] = []
    for item in from_env:
        # `--config-env=key=VAR`: git reads the value from $VAR.
        key, _, variable = item.partition("=")
        values = command.env_values(variable)
        config += [f"{key}={value}" for value in values]
        if not values:
            unresolved.append(key.lower())
    if not arg and not config and not unresolved:
        return None
    rest = tuple(args[index + 1:]) if arg else ()
    return Git(arg, rest, tuple(_normalize_config(c) for c in config), tuple(unresolved),
               tuple(dict.fromkeys(os.path.normpath(d) for d in directories)))


def _normalize_config(item: str) -> str:
    key, sep, value = item.partition("=")
    return f"{key.lower()}{sep}{value}"


def _git(sub: str | tuple[str, ...]):
    """Decorator: run `check` only for the named git subcommand(s)."""
    names = (sub,) if isinstance(sub, str) else sub

    def wrap(check):
        def matcher(command: SimpleCommand, ctx: RuleContext) -> str | None:
            git = git_invocation(command)
            if git is None or git.subcommand not in names:
                return None
            return check(git, ctx)
        return matcher
    return wrap


# --------------------------------------------------------------------------- #
# Discarding uncommitted work
# --------------------------------------------------------------------------- #


@_git("reset")
def _reset_hard(git: Git, ctx: RuleContext) -> str | None:
    if long_flag(git.args, "--hard", min_prefix=4):
        return "git reset --hard"
    if long_flag(git.args, "--merge", min_prefix=4):
        return "git reset --merge"
    return None


def _looks_like_path(operand: str, directories: tuple[str, ...]) -> bool:
    if operand in (".", "..") or operand.startswith(("./", "../", "/", ":")) or operand.endswith("/"):
        return True
    if any(ch in operand for ch in "*?["):
        return True  # a pathspec glob; branch names cannot contain these
    return any(os.path.exists(os.path.join(directory, operand)) for directory in directories)


def _is_ref(name: str, directories: tuple[str, ...]) -> bool:
    """`git checkout foo` switches to a branch or tag named foo when one exists,
    even if a file foo exists too: look it up in the repository's refs."""
    if name in ("HEAD", "-", "@") or name.startswith(("@{", "HEAD~", "HEAD^")):
        return True
    for directory in directories:
        git_dir = _git_dir(directory)
        if git_dir is None:
            continue
        for kind in ("heads", "tags"):
            if os.path.isfile(os.path.join(git_dir, "refs", kind, name)):
                return True
        try:
            with open(os.path.join(git_dir, "packed-refs"), encoding="utf-8", errors="replace") as handle:
                if any(line.rstrip("\n").endswith((f" refs/heads/{name}", f" refs/tags/{name}")) for line in handle):
                    return True
        except OSError:
            pass
    return False


def _git_dir(directory: str) -> str | None:
    """The .git directory of the repository `directory` is in, if any."""
    current = os.path.abspath(directory)
    while True:
        candidate = os.path.join(current, ".git")
        if os.path.isdir(candidate):
            return candidate
        if os.path.isfile(candidate):  # a worktree or submodule: `gitdir: PATH`
            try:
                with open(candidate, encoding="utf-8", errors="replace") as handle:
                    line = handle.readline().strip()
                if line.startswith("gitdir:"):
                    return os.path.normpath(os.path.join(current, line[7:].strip()))
            except OSError:
                return None
        parent = os.path.dirname(current)
        if parent == current:
            return None
        current = parent


# `git checkout` options that take a separate value.
_CHECKOUT_WITH_VALUE = frozenset({"--conflict", "--inter-hunk-context", "--unified", "-U",
                                  "--pathspec-from-file", "--orphan", "-b", "-B"})


@_git("checkout")
def _checkout_discard(git: Git, ctx: RuleContext) -> str | None:
    args = git.args
    # In `-bfeature` the rest of the cluster is the branch name, not flags.
    if short_flag(args, "f", with_value="UbB") or long_flag(args, "--force"):
        return "git checkout --force"  # discards local changes, new branch or not
    if short_flag(args, "bB", with_value="U") or long_flag(args, "--orphan"):
        return None  # creates a branch: nothing is discarded
    if long_flag(args, "--pathspec-from-file"):
        return "git checkout --pathspec-from-file"
    if "--" in args:
        if args[args.index("--") + 1:]:
            return "git checkout -- <path>"
        return None
    positionals = [p for p in operands(args, _CHECKOUT_WITH_VALUE) if p != "-"]
    if len(positionals) >= 2:
        return "git checkout <ref> <path>"
    directories = git.directories or (ctx.cwd,)
    if len(positionals) == 1 and _looks_like_path(positionals[0], directories) \
            and not _is_ref(positionals[0], directories):
        return f"git checkout {positionals[0]} (a path)"
    return None


@_git("switch")
def _switch_discard(git: Git, ctx: RuleContext) -> str | None:
    if long_flag(git.args, "--discard-changes"):
        return "git switch --discard-changes"
    if short_flag(git.args, "f", with_value="cC") or long_flag(git.args, "--force"):
        return "git switch --force"
    return None


@_git("restore")
def _restore_worktree(git: Git, ctx: RuleContext) -> str | None:
    args = git.args
    if has(args, "-h", "--help", "--version"):
        return None
    pathspecs = operands(args, frozenset({"-s", "--source", "--conflict", "--inter-hunk-context",
                                          "-U", "--unified"}))
    if not pathspecs and not long_flag(args, "--pathspec-from-file"):
        return None  # nothing named: git refuses to restore anything
    staged = short_flag(args, "S", with_value="sU") or has(args, "--staged")
    worktree = short_flag(args, "W", with_value="sU") or has(args, "--worktree")
    if has(args, "--no-worktree"):
        worktree = False
    elif not staged and not has(args, "--no-staged"):
        worktree = True  # git restore's default target is the working tree
    return "git restore (working tree)" if worktree else None


@_git("clean")
def _clean_force(git: Git, ctx: RuleContext) -> str | None:
    if short_flag(git.args, "n") or long_flag(git.args, "--dry-run"):
        return None
    if short_flag(git.args, "f") or long_flag(git.args, "--force"):
        return "git clean -f"
    return None


@_git("rm")
def _rm_force(git: Git, ctx: RuleContext) -> str | None:
    if long_flag(git.args, "--cached") or short_flag(git.args, "n") or long_flag(git.args, "--dry-run"):
        return None
    if short_flag(git.args, "f") or long_flag(git.args, "--force"):
        return "git rm -f"
    return None


@_git("stash")
def _stash_drop(git: Git, ctx: RuleContext) -> str | None:
    if git.args and git.args[0] in ("drop", "clear"):
        return f"git stash {git.args[0]}"
    return None


@_git("worktree")
def _worktree_remove_force(git: Git, ctx: RuleContext) -> str | None:
    if git.args and git.args[0] == "remove" and (short_flag(git.args[1:], "f") or long_flag(git.args[1:], "--force")):
        return "git worktree remove --force"
    return None


# --------------------------------------------------------------------------- #
# Rewriting or deleting history and refs
# --------------------------------------------------------------------------- #


_SAFE_FORCE = frozenset({"--force-with-lease", "--force-if-includes"})


def _forces(args: tuple[str, ...]) -> bool:
    """`-f`, `--force` or a prefix of it; never `--force-with-lease`/`--force-if-includes`."""
    for arg in args:
        if arg == "--":
            return False
        key = arg.split("=", 1)[0]
        if key in _SAFE_FORCE:
            continue
        if key.startswith("--") and len(key) >= 6 and "--force".startswith(key):
            return True
        if arg.startswith("-") and not arg.startswith("--") and "f" in arg[1:]:
            return True
    return False


_PUSH_WITH_VALUE = frozenset({"--repo", "-o", "--push-option", "--receive-pack", "--exec"})


def _push_refspecs(args: tuple[str, ...]) -> list[str]:
    """`git push [<repository> [<refspec>...]]`; with `--repo` every operand is a refspec."""
    words = operands(args, _PUSH_WITH_VALUE)
    names_repo = any(a == "--repo" or a.startswith("--repo=") for a in args)
    return words if names_repo else words[1:]


@_git("push")
def _push_force(git: Git, ctx: RuleContext) -> str | None:
    args = git.args
    if long_flag(args, "--mirror"):
        return "git push --mirror"
    if _forces(args):
        return "git push --force"
    if any(r.startswith("+") or ":+" in r for r in _push_refspecs(args)):
        return "git push +refspec (force)"
    return None


@_git("push")
def _push_delete(git: Git, ctx: RuleContext) -> str | None:
    if short_flag(git.args, "d") or long_flag(git.args, "--delete"):
        return "git push --delete"
    if long_flag(git.args, "--prune"):
        # Deletes remote branches the refspec matches but that have no local counterpart.
        return "git push --prune"
    if any(r.startswith(":") and len(r) > 1 for r in _push_refspecs(git.args)):
        return "git push :ref (delete)"
    return None


@_git("branch")
def _branch_force_delete(git: Git, ctx: RuleContext) -> str | None:
    args = git.args
    if short_flag(args, "D"):
        return "git branch -D"
    deleting = short_flag(args, "d") or long_flag(args, "--delete")
    forcing = short_flag(args, "f") or long_flag(args, "--force")
    return "git branch --delete --force" if deleting and forcing else None


@_git("tag")
def _tag_delete(git: Git, ctx: RuleContext) -> str | None:
    return "git tag -d" if short_flag(git.args, "d") or long_flag(git.args, "--delete") else None


@_git("reflog")
def _reflog_delete(git: Git, ctx: RuleContext) -> str | None:
    if git.args and git.args[0] == "delete":
        return "git reflog delete"
    if git.args and git.args[0] == "expire" and any(a.startswith("--expire") and a.endswith(("now", "all")) for a in git.args):
        return "git reflog expire --expire=now"
    return None


@_git(("filter-branch", "filter-repo"))
def _filter_history(git: Git, ctx: RuleContext) -> str | None:
    return f"git {git.subcommand}"


@_git("update-ref")
def _update_ref_delete(git: Git, ctx: RuleContext) -> str | None:
    return "git update-ref -d" if short_flag(git.args, "d") or long_flag(git.args, "--delete") else None


@_git(("rebase", "merge", "cherry-pick", "revert", "am"))
def _abort_in_progress(git: Git, ctx: RuleContext) -> str | None:
    return f"git {git.subcommand} --abort" if has(git.args, "--abort") else None


# --------------------------------------------------------------------------- #
# Config that hides commands or weakens git's own checks
# --------------------------------------------------------------------------- #


def _config_assignments(command: SimpleCommand) -> list[tuple[str, str]]:
    """(key, value) pairs set by `git -c k=v` or `git config [--global] k v`."""
    git = git_invocation(command)
    if git is None:
        return []
    pairs = [(c.partition("=")[0], c.partition("=")[2]) for c in git.config]
    if git.subcommand == "config":
        positional = operands(git.args, frozenset({"-f", "--file", "--blob", "--type", "--default",
                                                   "--comment", "--value"}))
        if positional and positional[0] == "set":
            positional = positional[1:]
        if len(positional) >= 2 and "." in positional[0]:
            pairs.append((positional[0].lower(), positional[1]))
    return pairs


def _hooks_path(command: SimpleCommand, ctx: RuleContext) -> str | None:
    for key, _ in _config_assignments(command):
        if key == "core.hookspath":
            return "git core.hooksPath"
    return None


def _shell_alias(command: SimpleCommand, ctx: RuleContext) -> str | None:
    for key, value in _config_assignments(command):
        if key.startswith("alias.") and value.lstrip().startswith("!"):
            return f"git {key} = !shell"
    return None


# Keys whose value is a program git runs. Set inline with `-c`, they execute
# an arbitrary command under an innocuous-looking git invocation.
_NETWORK_SUBCOMMANDS = frozenset({"clone", "fetch", "pull", "push", "ls-remote", "submodule",
                                  "remote", "archive"})
_PROGRAM_KEYS = frozenset({"core.sshcommand", "core.fsmonitor", "core.pager", "core.editor",
                           "core.askpass", "credential.helper", "diff.external", "sequence.editor"})


# Per-driver keys whose value is a command git runs through the shell:
# `filter.X.clean`/`smudge`/`process`, `diff.X.textconv`/`command`, `merge.X.driver`.
_PROGRAM_KEY_PATTERN = re.compile(r"filter\.[^=]+\.(?:clean|smudge|process)|diff\.[^=]+\.(?:textconv|command)"
                                  r"|merge\.[^=]+\.driver|gpg(?:\.[^=]+)?\.program|core\.gitproxy")


# `protocol.ext.allow=always` lets any URL run a program through git-remote-ext;
# `protocol.allow=always` does the same for every transport (PR review).
_PROTOCOL_KEYS = frozenset({"protocol.ext.allow", "protocol.allow"})


def _unsafe_override(command: SimpleCommand, ctx: RuleContext) -> str | None:
    git = git_invocation(command)
    for key, value in _config_assignments(command):
        if key == "http.sslverify" and value.lower() in ("false", "0", "no", "off"):
            return "git http.sslVerify=false"
        if key in _PROTOCOL_KEYS and value.lower() == "always":
            return f"git {key}=always"
        # `git config core.fsmonitor PROG` stores a program every later git status
        # runs silently. (Editor, pager, credential helper, sshCommand are routine
        # settings the user sees run; true/false selects the built-in fsmonitor.)
        if git and git.subcommand == "config" and key == "core.fsmonitor" \
                and value.lower() not in ("true", "false", "yes", "no", "on", "off", "1", "0", ""):
            return "git config core.fsmonitor <program>"
    for item in git.config if git else ():
        key = item.partition("=")[0].lower()
        if _PROGRAM_KEY_PATTERN.fullmatch(key):
            return f"git -c {key}=..."
        # sshCommand only runs on network operations; the rest run on most commands.
        if key == "core.sshcommand" and git.subcommand not in _NETWORK_SUBCOMMANDS:
            continue
        if key in _PROGRAM_KEYS:
            return f"git -c {key}=..."
    return None


def _config_from_unknown_env(command: SimpleCommand, ctx: RuleContext) -> str | None:
    git = git_invocation(command)
    for key in git.unresolved if git else ():
        if key.startswith("alias.") or key in _PROGRAM_KEYS or key in ("core.hookspath", "http.sslverify") \
                or key in _PROTOCOL_KEYS \
                or _PROGRAM_KEY_PATTERN.fullmatch(key.lower()):
            return f"git --config-env={key}=<unknown value>"
    return None


def _ext_transport(command: SimpleCommand, ctx: RuleContext) -> str | None:
    """An `ext::CMD` URL makes git run CMD as the transport (git-remote-ext), on
    clone, fetch, pull, push, ls-remote, remote add or submodule add (PR review)."""
    git = git_invocation(command)
    for arg in git.args if git else ():
        if arg.startswith("ext::"):
            return f"git {git.subcommand} ext::"
    return None


def _no_verify(command: SimpleCommand, ctx: RuleContext) -> str | None:
    git = git_invocation(command)
    if git and git.subcommand in ("commit", "push", "merge", "am", "rebase") and has(git.args, "--no-verify"):
        return f"git {git.subcommand} --no-verify"
    return None


_DISCARD_HINT = (
    "This discards uncommitted or unpushed work with no undo. Show the user what would be "
    "lost (`git status`, `git diff`, `git stash list`) and let them decide, or use the safe "
    "form: `git stash` to set changes aside, `git restore --staged` to unstage only."
)
_HISTORY_HINT = (
    "This rewrites or deletes history other people may have. Prefer `git push "
    "--force-with-lease`, `git branch -d` (refuses unmerged work), or ask the user to run it."
)

GIT_RULES: tuple[DangerRule, ...] = (
    DangerRule("git-reset-hard", HIGH, "git reset --hard/--merge discards uncommitted changes",
               _DISCARD_HINT, _reset_hard),
    DangerRule("git-checkout-discard", HIGH, "git checkout of paths or --force discards uncommitted changes",
               _DISCARD_HINT, _checkout_discard),
    DangerRule("git-switch-discard", HIGH, "git switch --force/--discard-changes discards local changes",
               _DISCARD_HINT, _switch_discard),
    DangerRule("git-restore-worktree", HIGH, "git restore of the working tree discards uncommitted changes",
               _DISCARD_HINT, _restore_worktree),
    DangerRule("git-clean-force", HIGH, "git clean -f deletes untracked files permanently",
               "Preview with `git clean -n` and let the user run the deletion.", _clean_force, decision="ask"),
    DangerRule("git-rm-force", HIGH, "git rm -f deletes files with uncommitted changes",
               "Use `git rm --cached` to untrack, or plain `git rm` which refuses modified files.", _rm_force, decision="ask"),
    DangerRule("git-stash-drop", HIGH, "dropping or clearing stashes loses stashed work",
               "Show `git stash list` and let the user drop it.", _stash_drop),
    DangerRule("git-worktree-remove-force", HIGH, "git worktree remove --force deletes uncommitted work",
               "Use `git worktree remove` without --force; it refuses dirty worktrees.", _worktree_remove_force),
    DangerRule("git-push-force", HIGH, "force push overwrites remote history",
               _HISTORY_HINT, _push_force),
    DangerRule("git-push-delete", HIGH, "git push --delete removes a remote branch or tag",
               _HISTORY_HINT, _push_delete),
    DangerRule("git-branch-force-delete", HIGH, "git branch -D deletes unmerged commits",
               _HISTORY_HINT, _branch_force_delete),
    DangerRule("git-tag-delete", HIGH, "deleting tags loses release markers", _HISTORY_HINT, _tag_delete),
    DangerRule("git-reflog-delete", HIGH, "deleting reflog entries removes the last way to recover commits",
               _HISTORY_HINT, _reflog_delete),
    DangerRule("git-filter-history", HIGH, "history rewriting tools rewrite every commit", _HISTORY_HINT,
               _filter_history),
    DangerRule("git-update-ref-delete", HIGH, "git update-ref -d deletes a ref directly", _HISTORY_HINT,
               _update_ref_delete),
    DangerRule("git-hooks-path", HIGH, "core.hooksPath redirects or disables git hooks",
               "Hooks are a control point; leave hook configuration to the user.", _hooks_path),
    DangerRule("git-shell-alias", HIGH, "a `!` alias runs an arbitrary shell command under a git name",
               "Run the command directly so it can be checked.", _shell_alias),
    DangerRule("git-ext-transport", HIGH, "an `ext::` URL runs an arbitrary command as git's transport",
               "Use an https:// or ssh:// URL. git-remote-ext executes the command in the URL.", _ext_transport),
    DangerRule("git-unsafe-override", HIGH, "disables TLS verification or runs a program through git config",
               "Do not weaken transport security or inject programs via `-c`; fix the underlying issue.",
               _unsafe_override),
    DangerRule("git-config-env-unknown", HIGH,
               "sets an alias, hook path or program through --config-env from a variable that cannot be checked",
               "Pass the value inline with `-c key=value` so it can be checked, or ask the user.",
               _config_from_unknown_env, decision="ask"),
    DangerRule("git-no-verify", HIGH, "--no-verify skips the repository's hooks and checks",
               "Fix what the hook reports instead of skipping it, or ask the user.", _no_verify,
               decision="ask"),
    DangerRule("git-abort", STRICT, "--abort throws away an in-progress merge/rebase resolution",
               "Confirm with the user before discarding conflict resolution work.", _abort_in_progress,
